def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 200:
                prev = opp.get('previous_trace', {})
                pb = prev.get('bid') if prev else None
                if pb is not None and pb >= DAILY_SALARY * 0.9:
                    rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            if prev:
                pb = prev.get('bid')
                if pb is not None:
                    prev_bids.append(float(pb))

    if not alive:
        return float(min(budget, 21.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = supply <= 17.0
    supply_loose = supply >= 22.0

    urgent = hp <= 3 or no_water >= 1
    very_urgent = hp <= 2 or no_water >= 2

    if very_urgent:
        bid = max(63.0, highest_prev + 2.0)
    elif urgent:
        if supply_tight:
            bid = max(52.0, highest_prev * 0.92 + 1.0)
        else:
            bid = max(44.0, avg_prev * 0.55)
    else:
        if supply_loose:
            bid = 12.0 if rich_aggressive >= 1 else 18.0
        elif supply_tight:
            if highest_prev >= 100.0:
                bid = 24.0
            else:
                bid = max(28.0, min(46.0, avg_prev * 0.45 + 4.0))
        else:
            if rich_aggressive >= 2:
                bid = 20.0
            elif highest_prev >= 100.0:
                bid = 26.0
            else:
                bid = max(24.0, min(40.0, avg_prev * 0.4 + 6.0))

    if day >= 8 and hp <= 5:
        bid = max(bid, 48.0)

    if desperate_count >= 2 and not urgent:
        bid = min(bid, 26.0)

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 2.0
    elif day == 8:
        reserve = DAILY_SALARY * 1.2
    elif day == 9:
        reserve = DAILY_SALARY * 0.6

    affordable = budget - reserve
    if affordable < 0:
        affordable = budget * 0.35

    bid = min(bid, budget, affordable if affordable > 0 else budget)
    if urgent:
        bid = min(max(bid, 35.0), budget)

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive.append((oid, o))
        except Exception:
            continue

    # If no opponents alive, conserve budget
    if not alive:
        return max(0.0, min(float(my_status['budget']), DAILY_SALARY * 0.35))

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how aggressive the table is
    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_highest = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_highest = sorted_bids[1]

    # Supply pressure: higher supply means cheaper to secure water.
    # Normalize to [0,1]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # If we are in danger (low hp or many no-water days), bid more.
    danger = (my_hp <= 2.5) or (my_no_water_days >= 2)

    # Cindy-like behavior: very high bids (~>=110). We can try to undercut.
    # Target bid uses highest_prev but caps to avoid overspending.
    # Undercut by a small amount if we can.
    if highest_prev >= 100.0:
        base_target = highest_prev - 6.0
    elif highest_prev >= 60.0:
        base_target = highest_prev - 4.0
    else:
        base_target = max(DAILY_SALARY * 0.45, second_highest + 3.0)

    # Adjust for supply: when supply is high, we can bid less.
    # When supply is low, bid more.
    # supply_norm near 1 -> discount; near 0 -> increase.
    if supply_norm >= 0.7:
        base_target *= 0.82
    elif supply_norm <= 0.3:
        base_target *= 1.12

    # Safety floors/ceilings
    if danger:
        base_target = max(base_target, DAILY_SALARY * 0.85)
    else:
        base_target = max(base_target, DAILY_SALARY * 0.52)

    # Never exceed budget
    bid = min(my_budget, base_target)

    # If budget is tiny, still bid what we can (non-negative)
    if bid < 0.0:
        bid = 0.0

    # Additional micro-adjustment by day parity to avoid ties with predictable bots
    # (small perturbation)
    if day % 2 == 0:
        bid *= 0.995
    else:
        bid *= 1.005

    # Final clamp
    if my_budget <= 0.0:
        return 0.0
    return float(min(my_budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        target = min(avg_prev * 1.1, DAILY_SALARY * 0.8)
        return min(my_status['budget'], max(target, 45))

    return min(my_status['budget'], 50)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Determine base bid considering supply scarcity
    # At low supply, competition is higher.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)  # 0 when min, 1 when max

    # Base bid as fraction of salary, adjusted by supply
    if supply < WATER_REQ * len(alive_opponents) + 1:
        # Very scarce: need to bid high
        base_fraction = 0.7 + (1 - supply_ratio) * 0.2
    else:
        base_fraction = 0.5 + (1 - supply_ratio) * 0.1

    # Use opponent's previous bid to adjust
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
        # If opponents were aggressive yesterday, be cautious unless desperate
        if max_prev_bid > DAILY_SALARY * 0.85:
            if hp > 3:
                target_bid = DAILY_SALARY * 0.4
            else:
                target_bid = DAILY_SALARY * 0.9
        else:
            # Bid slightly above average to secure water but not overpay
            target_bid = max(DAILY_SALARY * base_fraction, avg_prev_bid + 1.5)
    else:
        # No history: bid based on hp
        if hp <= 2:
            target_bid = DAILY_SALARY * 0.9
        elif hp <= 4:
            target_bid = DAILY_SALARY * 0.7
        else:
            target_bid = DAILY_SALARY * base_fraction

    # Ensure we don't bid more than budget
    bid = min(budget, target_bid)
    # Also ensure at least 1 to have a chance
    return max(1, bid)
